local ChronicleBinder = {}
local PRODUCTS = {
    simple_chronicle_volume = { name = "Preprost kronika zvezek", parchmentCost = 3, leatherCost = 1, threadCost = 1, time = 5, cost = 80, education = 18, happiness = 1, description = "Preprost kronika zvezek za zgodovino." },
    illustrated_chronicle = { name = "Ilustrirana kronika", parchmentCost = 3, leatherCost = 1, paintCost = 1, threadCost = 1, time = 8, cost = 220, education = 32, happiness = 2, prestige = 2, description = "Ilustrirana kronika za trgovce." },
    silver_clasped_chronicle = { name = "Srebrnosponka kronika", parchmentCost = 3, silverCost = 1, leatherCost = 1, paintCost = 1, threadCost = 1, time = 11, cost = 540, education = 48, happiness = 2, prestige = 6, description = "Srebrnosponka kronika za plemiče." },
    gold_trimmed_chronicle = { name = "Zlatookrasna kronika", parchmentCost = 3, goldCost = 1, silverCost = 1, leatherCost = 1, paintCost = 1, threadCost = 1, time = 15, cost = 1300, education = 62, happiness = 3, prestige = 14, description = "Zlatookrasna kronika za visoke plemiče." },
    jewel_set_chronicle = { name = "Draguljasta kronika", parchmentCost = 4, goldCost = 1, silverCost = 1, leatherCost = 1, paintCost = 1, threadCost = 1, jewelCost = 1, time = 19, cost = 2900, education = 78, happiness = 5, prestige = 27, description = "Kronika z draguljem za visoko plemstvo." },
    royal_grand_chronicle = { name = "Kraljevski veliki kronika", parchmentCost = 5, goldCost = 2, silverCost = 2, leatherCost = 1, paintCost = 1, threadCost = 1, jewelCost = 2, pearlCost = 2, time = 26, cost = 6200, education = 92, happiness = 12, prestige = 58, description = "Velika kraljevska kronika z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    chronicle_workshop = { name = "Kronikarska delavnica", cost = { gold = 260, wood = 100, stone = 100, parchment = 6, leather = 6 }, upkeep = 6, qualityBonus = 5 },
    archive_loft = { name = "Arhivska podstrešje", cost = { gold = 950, wood = 240, stone = 220, silver = 6, paint = 6 }, upkeep = 22, qualityBonus = 18 },
    master_chronicler_atelier = { name = "Mojstrski kronikarski atelje", cost = { gold = 2700, wood = 360, stone = 480, silver = 32, gold = 6 }, upkeep = 62, qualityBonus = 30 },
    royal_archive_palace = { name = "Kraljevska arhivska palača", cost = { gold = 11500, wood = 580, stone = 760, gold = 75, jewel = 18 }, upkeep = 230, qualityBonus = 55, prestigeBonus = 50 },
}
ChronicleBinder.parchmentStock = 16; ChronicleBinder.leatherStock = 12; ChronicleBinder.threadStock = 12; ChronicleBinder.paintStock = 10; ChronicleBinder.silverStock = 6; ChronicleBinder.goldStock = 6; ChronicleBinder.jewelStock = 4; ChronicleBinder.pearlStock = 4
ChronicleBinder.productStock = {}; ChronicleBinder.buildings = {}; ChronicleBinder.maker = nil; ChronicleBinder.activeMaking = {}; ChronicleBinder.totalProducts = 0; ChronicleBinder.dayTimer = 0
function ChronicleBinder.init() ChronicleBinder.parchmentStock=16; ChronicleBinder.leatherStock=12; ChronicleBinder.threadStock=12; ChronicleBinder.paintStock=10; ChronicleBinder.silverStock=6; ChronicleBinder.goldStock=6; ChronicleBinder.jewelStock=4; ChronicleBinder.pearlStock=4; ChronicleBinder.productStock={}; ChronicleBinder.buildings={}; ChronicleBinder.maker=nil; ChronicleBinder.activeMaking={}; ChronicleBinder.totalProducts=0; ChronicleBinder.dayTimer=0; print("[ChronicleBinder] Royal Chronicle Binder System initialized (6 products, 4 buildings)") end
function ChronicleBinder.hireMaker(n,s) s=s or math.random(55,90); local c=540+s*11; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; ChronicleBinder.maker={name=n or ("Kronikar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kronikar najet: %s (spretnost: %d)",ChronicleBinder.maker.name,s),"success") end; return true end
function ChronicleBinder.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function ChronicleBinder.build(id) local ok,e=ChronicleBinder.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(ChronicleBinder.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function ChronicleBinder.getQualityBonus() local b=0; for _,bd in ipairs(ChronicleBinder.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function ChronicleBinder.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.parchmentCost and ChronicleBinder.parchmentStock<(d.parchmentCost or 0) then return false,"Premalo pergamenta" end; if d.leatherCost and ChronicleBinder.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.threadCost and ChronicleBinder.threadStock<(d.threadCost or 0) then return false,"Premalo niti" end; if d.paintCost and ChronicleBinder.paintStock<(d.paintCost or 0) then return false,"Premalo barve" end; if d.silverCost and ChronicleBinder.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and ChronicleBinder.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and ChronicleBinder.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and ChronicleBinder.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #ChronicleBinder.buildings==0 then return false,"Potrebna kronikarska delavnica" end; if not ChronicleBinder.maker then return false,"Potreben kronikar" end; return true end
function ChronicleBinder.make(pt,qty) qty=qty or 1; local ok,e=ChronicleBinder.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.parchmentCost then ChronicleBinder.parchmentStock=ChronicleBinder.parchmentStock-d.parchmentCost*qty end; if d.leatherCost then ChronicleBinder.leatherStock=ChronicleBinder.leatherStock-d.leatherCost*qty end; if d.threadCost then ChronicleBinder.threadStock=ChronicleBinder.threadStock-d.threadCost*qty end; if d.paintCost then ChronicleBinder.paintStock=ChronicleBinder.paintStock-d.paintCost*qty end; if d.silverCost then ChronicleBinder.silverStock=ChronicleBinder.silverStock-d.silverCost*qty end; if d.goldCost then ChronicleBinder.goldStock=ChronicleBinder.goldStock-d.goldCost*qty end; if d.jewelCost then ChronicleBinder.jewelStock=ChronicleBinder.jewelStock-d.jewelCost*qty end; if d.pearlCost then ChronicleBinder.pearlStock=ChronicleBinder.pearlStock-d.pearlCost*qty end; local t=d.time; if ChronicleBinder.maker then t=math.max(1,t-math.floor(ChronicleBinder.maker.skill/12)) end; table.insert(ChronicleBinder.activeMaking,{id="chronicle_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,education=d.education or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Vezava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function ChronicleBinder.completeMaking(m) local q=1.0+(ChronicleBinder.getQualityBonus()/100); if ChronicleBinder.maker then q=q+(ChronicleBinder.maker.skill/140) end; q=math.min(2.5,q); ChronicleBinder.productStock[m.productType]=(ChronicleBinder.productStock[m.productType] or 0)+m.quantity; ChronicleBinder.totalProducts=ChronicleBinder.totalProducts+m.quantity; if m.education>0 and _G.state then _G.state.education=(_G.state.education or 0)+m.education end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if ChronicleBinder.maker then ChronicleBinder.maker.itemsMade=ChronicleBinder.maker.itemsMade+m.quantity; if math.random()<0.25 then ChronicleBinder.maker.skill=math.min(100,ChronicleBinder.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kronika izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"chronicle.completed",{productName=m.productName,education=m.education,prestige=m.prestige,happiness=m.happiness}) end end
function ChronicleBinder.update(dt) if not _G.state then return end; ChronicleBinder.dayTimer=ChronicleBinder.dayTimer+dt; if ChronicleBinder.dayTimer>=30 then ChronicleBinder.dayTimer=0; for i=#ChronicleBinder.activeMaking,1,-1 do local m=ChronicleBinder.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then ChronicleBinder.completeMaking(m); table.remove(ChronicleBinder.activeMaking,i) end end; local tu=0; for _,bd in ipairs(ChronicleBinder.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if ChronicleBinder.maker then tu=tu+14 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function ChronicleBinder.getStats() return {parchmentStock=ChronicleBinder.parchmentStock,leatherStock=ChronicleBinder.leatherStock,threadStock=ChronicleBinder.threadStock,paintStock=ChronicleBinder.paintStock,silverStock=ChronicleBinder.silverStock,goldStock=ChronicleBinder.goldStock,jewelStock=ChronicleBinder.jewelStock,pearlStock=ChronicleBinder.pearlStock,productStock=ChronicleBinder.productStock,numBuildings=#ChronicleBinder.buildings,hasMaker=ChronicleBinder.maker~=nil,makerName=ChronicleBinder.maker and ChronicleBinder.maker.name or "—",makerSkill=ChronicleBinder.maker and ChronicleBinder.maker.skill or 0,activeMaking=#ChronicleBinder.activeMaking,totalProducts=ChronicleBinder.totalProducts} end
return ChronicleBinder
